System.namespace("RobloxCSharp.Framework", function (namespace)
  -- Глобальный менеджер модификаторов: обновляет таймеры, тики и статы героев
  namespace.class("ModifierManager", function (namespace)
    local _allActiveModifiers, RegisterModifier, UnregisterModifier, UpdateStats, UpdateTick, static
    static = function (this)
      _allActiveModifiers = ListBaseModifier()
    end
    RegisterModifier = function (target, modifier)
      if target == nil or modifier == nil then
        return
      end

      target.Modifiers:Add(modifier)
      _allActiveModifiers:Add(modifier)

      UpdateStats(target)
    end
    UnregisterModifier = function (target, modifier)
      if target ~= nil then
        target.Modifiers:Remove(modifier)
        UpdateStats(target)
      end
      _allActiveModifiers:Remove(modifier)
    end
    UpdateStats = function (hero)
      if hero == nil or hero.Humanoid == nil or hero.IsDestroyed then
        return
      end

      local speedAdd = 0
      local jumpAdd = 0

      for _, mod in System.each(hero.Modifiers) do
        if mod.IsActive then
          speedAdd = speedAdd + mod:CheckWalkSpeedModifier()
          jumpAdd = jumpAdd + mod:CheckJumpPowerModifier()
        end
      end

      hero.Humanoid.WalkSpeed = hero.BaseWalkSpeed + speedAdd
      hero.Humanoid.JumpPower = hero.BaseJumpPower + jumpAdd
    end
    UpdateTick = function ()
      local now = System.DateTime.getUtcNow():getTicks() / 10000000.0

      for i = #_allActiveModifiers - 1, 0, -1 do
        local continue
        repeat
          local mod = _allActiveModifiers:get(i)
          if not mod.IsActive or mod.Target.IsDestroyed then
            mod:Destroy()
            continue = true
            break
          end

          -- 1. Проверка истечения времени действия
          if mod.Duration >= 0 and (now - mod.StartTime) >= mod.Duration then
            mod:Destroy()
            continue = true
            break
          end

          -- 2. Проверка тика интервала (OnIntervalThink)
          if mod.Interval > 0 and (now - mod.LastThinkTime) >= mod.Interval then
            mod.LastThinkTime = now
            mod:OnIntervalThink()
          end
          continue = true
        until 1
        if not continue then
          break
        end
      end
    end
    return {
      RegisterModifier = RegisterModifier,
      UnregisterModifier = UnregisterModifier,
      UpdateStats = UpdateStats,
      UpdateTick = UpdateTick,
